import re

def parse(lines):
    rows = []
    used = []
    skip = []
    group = None
    desc = ''
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        m = re.match(r'^(@[\w-]+)\s*$', line)
        if m:
            group = m.group(1)
            desc = ''
            used.append(i)
            continue
        m = re.match(r'^\s+#\s*(.*?)\s*$', line)
        if m:
            if group is not None:
                desc = m.group(1)
                used.append(i)
            else:
                skip.append(i)
            continue
        m = re.match(r'^\s+(\S+)\s*$', line)
        if m and group is not None:
            rows.append({'group': group, 'description': desc, 'syscall': m.group(1)})
            used.append(i)
            continue
    blocks = []
    if rows:
        blocks.append({'name': 'syscall_groups', 'kind': 'table', 'lines': used, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
